export type ProfileName = keyof typeof PROFILES;

/** Profiles keyed by canonical URL, for resolving `meta.profile`. */
export const PROFILES_BY_URL: ReadonlyMap<string, ProfileEntry> = new Map(
  Object.values(PROFILES).map((entry) => [entry.url, entry]),
);

/** The Composition profile each health information type is built on. */
export const HI_TYPE_PROFILES = {
  "DiagnosticReport": "DiagnosticReportRecord",
  "DischargeSummary": "DischargeSummaryRecord",
  "HealthDocumentRecord": "HealthDocumentRecord",
  "ImmunizationRecord": "ImmunizationRecord",
  "Invoice": "InvoiceRecord",
  "OPConsultation": "OPConsultRecord",
  "Prescription": "PrescriptionRecord",
  "WellnessRecord": "WellnessRecord"
} as const satisfies Record<HiType, ProfileName>;
